function rsv2_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function rsv2_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function rsv2_def():array{return ['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'salaryMasters'=>[],'rentMasters'=>[],'salaryPeriods'=>[],'rentPeriods'=>[],'salaryAdvances'=>[],'rentPrepayments'=>[],'rentSalaryPayments'=>[]];}
function rsv2_read():array{tt_ensure_data_dir();if(!is_file(RSV2_FILE))return rsv2_def();$h=fopen(RSV2_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(rsv2_def(),$v):rsv2_def();}
function rsv2_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))rsv2_out(['ok'=>false,'error'=>'Salary and mill rent are available for TTI / BRM.'],422);return $v;}
function rsv2_date(string $v,string $label='Date'):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))rsv2_out(['ok'=>false,'error'=>$label.' is required.'],422);return $v;}
function rsv2_month(string $v):string{if(!preg_match('/^\d{4}-\d{2}$/',$v))rsv2_out(['ok'=>false,'error'=>'Select a valid month.'],422);return $v;}
function rsv2_amt(mixed $v,string $label='Amount'):float{$n=round((float)$v,2);if($n<=0)rsv2_out(['ok'=>false,'error'=>$label.' must be greater than zero.'],422);return $n;}
function rsv2_mstart(string $m):string{return $m.'-01';}
function rsv2_mend(string $m):string{return (new DateTimeImmutable($m.'-01'))->modify('last day of this month')->format('Y-m-d');}
function rsv2_prev_day(string $d):string{return (new DateTimeImmutable($d))->modify('-1 day')->format('Y-m-d');}
