function rsv2_line(string $a,float $dr,float $cr,array $names,array $extra=[]):array{if(!isset($names[$a]))rsv2_out(['ok'=>false,'error'=>'Approved account '.$a.' is unavailable.'],422);return array_merge(['account'=>$a,'accountName'=>$names[$a],'debit'=>round($dr,2),'credit'=>round($cr,2)],$extra);}
function rsv2_active(array $m,string $month):bool{if(($m['status']??'Active')!=='Active')return false;$from=(string)($m['effectiveFrom']??'');$to=(string)($m['effectiveTo']??'');$ms=rsv2_mstart($month);$me=rsv2_mend($month);return ($from===''||$from<=$me)&&($to===''||$to>=$ms);}
function rsv2_cat(string $v):string{$v=strtoupper(trim($v));$ok=['MILL_STAFF','OFFICE_STAFF','HOME_STAFF','DIRECTOR_REMUNERATION','HOME_MONTHLY_GIVE'];if(!in_array($v,$ok,true))rsv2_out(['ok'=>false,'error'=>'Select a valid salary category.'],422);return $v;}
function rsv2_cat_name(string $v):string{return match($v){'MILL_STAFF'=>'Mill Staff','OFFICE_STAFF'=>'Office Staff','HOME_STAFF'=>'Home Staff','DIRECTOR_REMUNERATION'=>'Director Remuneration','HOME_MONTHLY_GIVE'=>'Home Monthly Give',default=>$v};}
function rsv2_default_treatment(string $cat):string{return match($cat){'MILL_STAFF','OFFICE_STAFF','HOME_STAFF'=>'STAFF_COST','HOME_MONTHLY_GIVE'=>'FAMILY_ALLOCATION',default=>'TO_CONFIRM'};}
