function rsv2_payment_accounts(array $s,string $entity):array{$o=[];foreach(rsv2_banks() as $id=>$a){if(($a['entity']??'')!==$entity||($a['accountType']??'')!=='Company Account'||($a['currency']??'')!=='PKR')continue;$set=is_array($s['bankAccountSettings'][$id]??null)?$s['bankAccountSettings'][$id]:[];if(empty($set['active'])||empty($set['allowPayments']))continue;$digits=preg_replace('/\D+/','',(string)$a['accountNumber'])??'';$o[]=['id'=>$id,'type'=>'BANK','label'=>trim((string)$a['bankName']).($digits!==''?' — '.substr($digits,-5):''),'bookBalance'=>rsv2_bank_bal($s,$entity,$id)];}$cash='CASH|'.$entity;$set=is_array($s['bankAccountSettings'][$cash]??null)?$s['bankAccountSettings'][$cash]:['active'=>true,'allowPayments'=>true];if(!empty($set['active'])&&!empty($set['allowPayments']))$o[]=['id'=>$cash,'type'=>'CASH','label'=>'Cash / Petty Cash','bookBalance'=>rsv2_cash_bal($s,$entity)];return $o;}
