function rsv2_journal(array &$s,string $entity,string $date,string $source,string $ref,string $narr,array $lines,array $u,array $meta=[]):string{$dr=round(array_sum(array_map(static fn($l)=>(float)($l['debit']??0),$lines)),2);$cr=round(array_sum(array_map(static fn($l)=>(float)($l['credit']??0),$lines)),2);if(abs($dr-$cr)>.005)throw new RuntimeException('Journal did not balance.');$id=rsv2_next((array)$s['journals'],'AUTO');$s['journals'][$id]=['id'=>$id,'entity'=>$entity,'date'=>$date,'sourceType'=>$source,'reference'=>$ref,'narration'=>$narr,'lines'=>$lines,'totalDebit'=>$dr,'totalCredit'=>$cr,'status'=>'Posted','meta'=>$meta,'createdAt'=>gmdate('c'),'createdBy'=>(string)($u['full_name']??$u['username']??'Accounts'),'userId'=>(int)($u['id']??0),'reversalOf'=>null];return $id;}
