function rsv2_salary_row(array $s,array $m,string $month):array{$pid=rsv2_pid((string)$m['entity'],$month,(string)$m['id']);$p=is_array($s['salaryPeriods'][$pid]??null)?$s['salaryPeriods'][$pid]:null;$paidAdv=0;foreach(rsv2_advances($s,(string)$m['id'],$month) as $a)$paidAdv+=(float)($a['amount']??0);return ['periodId'=>$pid,'masterId'=>$m['id'],'name'=>$m['name'],'category'=>$m['category'],'categoryName'=>rsv2_cat_name((string)$m['category']),'accountingTreatment'=>$m['accountingTreatment']??rsv2_default_treatment((string)$m['category']),'month'=>$month,'gross'=>(float)$m['monthlyAmount'],'advancePaid'=>round($paidAdv,2),'prepared'=>$p!==null,'appliedAdvance'=>(float)($p['appliedAdvance']??0),'paidAfterPrepare'=>(float)($p['paidAfterPrepare']??0),'outstanding'=>(float)($p['outstanding']??0),'productionCostEligible'=>(bool)($m['productionCostEligible']??false),'status'=>$p['status']??(($m['accountingTreatment']??'')==='TO_CONFIRM'?'Treatment Required':'Not Prepared')];}
